// Lexer: Source code → Tokens
// Tokenizes FV-Lang source code into a stream of tokens
// Security hardened with input validation and resource limits

use crate::CompileError;

// Security limits
const MAX_INPUT_SIZE: usize = 10_000_000;        // 10MB max
const MAX_IDENTIFIER_LENGTH: usize = 10_000;     // 10K chars max
const MAX_STRING_LENGTH: usize = 1_000_000;      // 1MB max
const MAX_NUMBER_LENGTH: usize = 100;            // 100 digits max

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Keywords
    Fn,
    Let,
    If,
    Else,
    Match,
    Return,
    Type,
    Mut,

    // Identifiers and literals
    Identifier(String),
    Integer(i64),
    Float(f64),
    String(String),
    True,
    False,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Assign,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
    Not,
    Arrow,      // ->
    FatArrow,   // =>
    Pipe,       // |

    // Delimiters
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Comma,
    Dot,
    Colon,
    Semicolon,

    // Special
    Eof,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
    column: usize,
}

impl Lexer {
    /// Create a new lexer with input size validation
    pub fn new(input: &str) -> Result<Self, CompileError> {
        // ✅ Check input size
        if input.len() > MAX_INPUT_SIZE {
            return Err(CompileError::LexerError(format!(
                "Input too large: {} bytes (max {} bytes)",
                input.len(),
                MAX_INPUT_SIZE
            )));
        }

        // ✅ Check for null bytes (security)
        if input.contains('\0') {
            return Err(CompileError::LexerError(
                "Input contains null bytes".to_string(),
            ));
        }

        Ok(Lexer {
            input: input.chars().collect(),
            pos: 0,
            line: 1,
            column: 1,
        })
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, CompileError> {
        let mut tokens = Vec::new();

        while self.pos < self.input.len() {
            // Skip whitespace
            if let Some(c) = self.current_char() {
                if c.is_whitespace() {
                    if c == '\n' {
                        self.line += 1;
                        self.column = 1;
                    } else {
                        self.column += 1;
                    }
                    self.advance();
                    continue;
                }
            }

            // Comments
            if self.peek_chars(2) == "//" {
                self.skip_line_comment();
                continue;
            }

            match self.current_char() {
                Some(c) if c.is_alphabetic() || c == '_' => {
                    tokens.push(self.read_identifier_or_keyword()?);
                }
                Some(c) if c.is_numeric() => {
                    tokens.push(self.read_number()?);
                }
                Some('"') => {
                    tokens.push(self.read_string()?);
                }
                Some('+') => {
                    tokens.push(Token::Plus);
                    self.advance();
                }
                Some('-') => {
                    if self.peek_chars(2) == "->" {
                        tokens.push(Token::Arrow);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Minus);
                        self.advance();
                    }
                }

