// Parser: Tokens → Abstract Syntax Tree
// Parses FV-Lang token stream into an AST
// Security hardened with recursion depth limits

use crate::{lexer::Token, ast::*, CompileError};

// Security limits
const MAX_PARSE_DEPTH: usize = 1000;  // 최대 파싱 깊이
const MAX_TOKENS: usize = 100_000;    // 최대 토큰 수

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    errors: Vec<CompileError>,  // ✅ 에러 수집
}

impl Parser {
    /// 토큰 배열 크기 검증과 함께 파서 생성
    pub fn new(tokens: Vec<Token>) -> Result<Self, CompileError> {
        if tokens.len() > MAX_TOKENS {
            return Err(CompileError::ParserError(format!(
                "토큰 수가 너무 많음: {} (최대 {})",
                tokens.len(),
                MAX_TOKENS
            )));
        }

        Ok(Parser {
            tokens,
            pos: 0,
            errors: Vec::new(),
        })
    }

    /// 에러 복구: 다음 동기화 포인트까지 스킵
    fn synchronize(&mut self) {
        self.advance();

        while !self.is_at_end() {
            if self.tokens.get(self.pos.saturating_sub(1)) == Some(&Token::Semicolon) {
                return;
            }

            match self.peek() {
                Token::Fn | Token::Type | Token::Let | Token::If | Token::Return => return,
                Token::RBrace | Token::Eof => return,
                _ => self.advance(),
            }
        }
    }

    pub fn parse(mut self) -> Result<Program, CompileError> {
        let mut definitions = Vec::new();
        let mut statements = Vec::new();

        while !self.is_at_end() {
            match self.peek() {
                Token::Fn => {
                    match self.parse_function() {
                        Ok(Some(def)) => definitions.push(def),
                        Ok(None) => break,
                        Err(_) => { self.synchronize(); }
                    }
                }
                Token::Type => {
                    match self.parse_type_def() {
                        Ok(Some(def)) => definitions.push(def),
                        Ok(None) => break,
                        Err(_) => { self.synchronize(); }
                    }
                }
                Token::Eof => break,
                // 최상위 구문 (let, 표현식 등)
                _ => {
                    match self.parse_statement() {
                        Ok(stmt) => statements.push(stmt),
                        Err(_) => { self.synchronize(); }
                    }
                }
            }
        }

        Ok(Program { definitions, statements })
    }

    fn parse_definition(&mut self) -> Result<Option<Definition>, CompileError> {
        match self.peek() {
            Token::Fn => self.parse_function(),
            Token::Type => self.parse_type_def(),
            Token::Eof => Ok(None),
            _ => Err(CompileError::ParserError(
                format!("Expected definition, found {:?}", self.peek()),
            )),
        }
    }

    fn parse_function(&mut self) -> Result<Option<Definition>, CompileError> {
        self.expect(Token::Fn)?;

        let name = match self.peek() {
            Token::Identifier(n) => {
                let name = n.clone();
                self.advance();
                name
            }
            _ => return Err(CompileError::ParserError("Expected function name".to_string())),
        };

        self.expect(Token::LParen)?;

        let mut params = Vec::new();
        while self.peek() != &Token::RParen {
            if !params.is_empty() {
                self.expect(Token::Comma)?;
            }

            if let Token::Identifier(param_name) = self.peek() {
                let param = param_name.clone();
                self.advance();
                // 타입 어노테이션 선택적: param: Type 또는 param
                if self.peek() == &Token::Colon {
                    self.advance();
                    let _param_type = self.parse_type()?;
                }
                params.push(param);
            }
        }

        self.expect(Token::RParen)?;
        self.expect(Token::Arrow)?;
        let _return_type = self.parse_type()?;

        self.expect(Token::LBrace)?;
        let body = self.parse_block()?;
        self.expect(Token::RBrace)?;

        Ok(Some(Definition::Function {
            name,
            params,
            body,
        }))
    }

    fn parse_type_def(&mut self) -> Result<Option<Definition>, CompileError> {
        self.expect(Token::Type)?;

        if let Token::Identifier(name) = self.peek() {
            let name = name.clone();
            self.advance();
            self.expect(Token::Assign)?;
            let _type_expr = self.parse_type()?;
            self.expect(Token::Semicolon)?;

            Ok(Some(Definition::TypeDef { name }))
        } else {
            Err(CompileError::ParserError("Expected type name".to_string()))
        }
    }

    fn parse_block(&mut self) -> Result<Vec<Statement>, CompileError> {
        let mut statements = Vec::new();

        while self.peek() != &Token::RBrace && !self.is_at_end() {
            statements.push(self.parse_statement()?);
        }

        Ok(statements)
    }

    fn parse_statement(&mut self) -> Result<Statement, CompileError> {
        match self.peek() {
            Token::Let => self.parse_let_binding(),
            Token::Return => self.parse_return(),
            Token::If => self.parse_if(),
            Token::Match => self.parse_match(),
            _ => self.parse_expression_statement(),
        }
    }

    fn parse_let_binding(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::Let)?;

        if let Token::Identifier(name) = self.peek() {
            let name = name.clone();
            self.advance();
            self.expect(Token::Assign)?;
            let expr = self.parse_expression()?;
            self.expect(Token::Semicolon)?;

            Ok(Statement::LetBinding {
                name,
                value: Box::new(expr),
            })
        } else {
            Err(CompileError::ParserError("Expected variable name".to_string()))
        }
    }

    fn parse_return(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::Return)?;

// Abstract Syntax Tree definitions for FV-Lang

#[derive(Debug, Clone)]
pub struct Program {
    pub definitions: Vec<Definition>,
    pub statements: Vec<Statement>,   // 최상위 실행 구문
}

#[derive(Debug, Clone)]
pub enum Definition {
    Function {
        name: String,
        params: Vec<String>,
        body: Vec<Statement>,
    },
    TypeDef {
        name: String,
    },
}

#[derive(Debug, Clone)]
pub enum Statement {
    LetBinding {
        name: String,
        value: Box<Expression>,
    },
    Return(Box<Expression>),
    If {
        condition: Box<Expression>,
        then_branch: Vec<Statement>,
        else_branch: Option<Vec<Statement>>,
    },
    Expression(Box<Expression>),
}

#[derive(Debug, Clone)]
pub enum Expression {
    Literal(Literal),
    Variable(String),
    BinaryOp {
        op: String,
        left: Box<Expression>,
        right: Box<Expression>,
    },
    UnaryOp {
        op: String,
        operand: Box<Expression>,
    },
    FunctionCall {
        name: String,
        args: Vec<Expression>,
    },
    IfExpr {
        condition: Box<Expression>,
        then_expr: Box<Expression>,
        else_expr: Option<Box<Expression>>,
    },
    Match {
        expr: Box<Expression>,
        patterns: Vec<(String, Box<Expression>)>,
    },
    Array {
        elements: Vec<Expression>,
    },
    Index {
        expr: Box<Expression>,
        index: Box<Expression>,
    },
    Tuple {
