// Parser: Tokens → Abstract Syntax Tree
// 토큰 스트림을 AST로 변환
// 재귀 하강 파싱 (Recursive Descent Parser)

// 파서 상태
type Parser = {
  tokens: Vec(Token),
  pos: i64,
}

// 파싱 결과
type ParseResult(T) =
  | Ok(T, Parser)
  | Err(String)

// 상수
fn MAX_PARSE_DEPTH() -> i64 {
  1000
}

fn MAX_TOKENS() -> i64 {
  100_000
}

// ============================================================================
// Parser Creation
// ============================================================================

fn create_parser(tokens: Vec(Token)) -> ParseResult(Parser) {
  if vec_length(tokens) > MAX_TOKENS() {
    Err("Too many tokens")
  } else {
    Ok(
      Parser {
        tokens: tokens,
        pos: 0,
      },
      Parser { tokens: tokens, pos: 0 }
    )
  }
}

// ============================================================================
// Low-level Parser Functions
// ============================================================================

// 현재 토큰 반환
fn peek(parser: Parser) -> Token {
  let tokens = parser.tokens;
  let pos = parser.pos;
  if pos >= vec_length(tokens) {
    Eof
  } else {
    vec_get(tokens, pos)
  }
}

// 다음 토큰으로 진행
fn advance(parser: Parser) -> Parser {
  Parser {
    tokens: parser.tokens,
    pos: parser.pos + 1,
  }
}

// 현재 위치 끝났나?
fn is_at_end(parser: Parser) -> bool {
  parser.pos >= vec_length(parser.tokens)
}

// 토큰 매칭
fn match_token(parser: Parser, expected: Token) -> ParseResult(Parser) {
  if token_equals(peek(parser), expected) {
    Ok(advance(parser), parser)
  } else {
    Err("Token mismatch")
  }
}

// 토큰이 특정 타입인지 확인
fn token_equals(t1: Token, t2: Token) -> bool {
  match (t1, t2) {
    (Fn, Fn) => true,
    (Let, Let) => true,
    (If, If) => true,
    (Else, Else) => true,
    (Match, Match) => true,
    (Return, Return) => true,
    (Type, Type) => true,
    (Identifier(_), Identifier(_)) => true,
    (Integer(_), Integer(_)) => true,
    (Float(_), Float(_)) => true,
    (String(_), String(_)) => true,
    (True, True) => true,
    (False, False) => true,
    (Plus, Plus) => true,
    (Minus, Minus) => true,
    (Star, Star) => true,
    (Slash, Slash) => true,
    (Eq, Eq) => true,
    (Lt, Lt) => true,
    (Gt, Gt) => true,
    (LParen, LParen) => true,
    (RParen, RParen) => true,
    (LBrace, LBrace) => true,
    (RBrace, RBrace) => true,
    (LBracket, LBracket) => true,
    (RBracket, RBracket) => true,
    (Comma, Comma) => true,
    (Dot, Dot) => true,
    (Colon, Colon) => true,
    (Semicolon, Semicolon) => true,
    (Arrow, Arrow) => true,
    (FatArrow, FatArrow) => true,
    (Eof, Eof) => true,
    _ => false,
  }
}

// ============================================================================
// Main Parser
// ============================================================================

fn parse(parser: Parser) -> ParseResult(Program) {
  parse_definitions(parser, [], [])
}

fn parse_definitions(
  parser: Parser,
  defs: Vec(Definition),
  stmts: Vec(Statement)
) -> ParseResult(Program) {
  if is_at_end(parser) {
    Ok(
      Program {
        definitions: defs,
        statements: stmts,
      },
      parser
    )
  } else {
    match peek(parser) {
      Fn => {
        match parse_function(parser) {
          Ok(def, parser2) => {
            let new_defs = vec_append(defs, def);
            parse_definitions(parser2, new_defs, stmts)
          }
          Err(e) => Err(e)
        }
      }
      Type => {
        match parse_type_def(parser) {
          Ok(def, parser2) => {
            let new_defs = vec_append(defs, def);
            parse_definitions(parser2, new_defs, stmts)
          }
          Err(e) => Err(e)
        }
      }
      Eof => {
        Ok(
          Program {
            definitions: defs,
            statements: stmts,
          },
          parser
        )
      }
      _ => {
        match parse_statement(parser) {
          Ok(stmt, parser2) => {
            let new_stmts = vec_append(stmts, stmt);
            parse_definitions(parser2, defs, new_stmts)
          }
          Err(e) => Err(e)
        }
      }
    }
  }
}

// ============================================================================
// Function Definition
// ============================================================================

fn parse_function(parser: Parser) -> ParseResult(Definition) {
  // expect Fn
  match match_token(parser, Fn) {
    Ok(parser2, _) => {
      // read function name
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          // expect (
          match match_token(parser3, LParen) {
            Ok(parser4, _) => {
              // parse parameters
              match parse_parameters(parser4, []) {
                Ok(params, parser5) => {
                  // expect )
                  match match_token(parser5, RParen) {
                    Ok(parser6, _) => {
                      // expect ->
                      match match_token(parser6, Arrow) {
                        Ok(parser7, _) => {
                          // parse return type (skip for now)
                          let parser8 = skip_type(parser7);
                          // expect {
                          match match_token(parser8, LBrace) {
                            Ok(parser9, _) => {
                              // parse body
                              match parse_block(parser9, []) {
                                Ok(body, parser10) => {
                                  // expect }
                                  match match_token(parser10, RBrace) {
                                    Ok(parser11, _) => {
                                      let def = Function {
                                        name: name,
                                        params: params,
                                        body: body,
                                      };
                                      Ok(def, parser11)
                                    }
                                    Err(e) => Err(e)
                                  }
                                }
                                Err(e) => Err(e)
                              }
                            }
                            Err(e) => Err(e)
                          }
                        }
                        Err(e) => Err(e)
                      }
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected function name")
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_parameters(parser: Parser, params: Vec(String)) -> ParseResult(Vec(String)) {
  if token_equals(peek(parser), RParen) {
    Ok(params, parser)
  } else {
    match peek(parser) {
      Identifier(name) => {
        let parser2 = advance(parser);
        // skip optional type annotation
        let parser3 = if token_equals(peek(parser2), Colon) {
          let p = advance(parser2);
          skip_type(p)
        } else {
          parser2
        };
        let new_params = vec_append(params, name);
        if token_equals(peek(parser3), Comma) {
          parse_parameters(advance(parser3), new_params)
        } else {
          Ok(new_params, parser3)
        }
      }
      _ => Err("Expected parameter name")
    }
  }
}

// ============================================================================
// Type Definition
// ============================================================================

fn parse_type_def(parser: Parser) -> ParseResult(Definition) {
  match match_token(parser, Type) {
    Ok(parser2, _) => {
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          match match_token(parser3, Assign) {
            Ok(parser4, _) => {
              let parser5 = skip_type(parser4);
              match match_token(parser5, Semicolon) {
                Ok(parser6, _) => {
                  let def = TypeDef { name: name };
                  Ok(def, parser6)
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected type name")
      }
    }
    Err(e) => Err(e)
  }
}

// ============================================================================
// Block Parsing
// ============================================================================

fn parse_block(parser: Parser, stmts: Vec(Statement)) -> ParseResult(Vec(Statement)) {
  if token_equals(peek(parser), RBrace) || is_at_end(parser) {
    Ok(stmts, parser)
  } else {
    match parse_statement(parser) {
      Ok(stmt, parser2) => {
        let new_stmts = vec_append(stmts, stmt);
        parse_block(parser2, new_stmts)
      }
      Err(e) => Err(e)
    }
  }
}

// ============================================================================
// Statement Parsing
// ============================================================================

fn parse_statement(parser: Parser) -> ParseResult(Statement) {
  match peek(parser) {
    Let => parse_let_binding(parser),
    Return => parse_return(parser),
    If => parse_if(parser),
    Match => parse_match(parser),
    _ => parse_expression_statement(parser),
  }
}

fn parse_let_binding(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, Let) {
    Ok(parser2, _) => {
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          match match_token(parser3, Assign) {
            Ok(parser4, _) => {
              match parse_expression(parser4) {
                Ok(expr, parser5) => {
                  match match_token(parser5, Semicolon) {
                    Ok(parser6, _) => {
                      let stmt = LetBinding {
                        name: name,
                        value: expr,
                      };
                      Ok(stmt, parser6)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected variable name")
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_return(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, Return) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(expr, parser3) => {
          match match_token(parser3, Semicolon) {
            Ok(parser4, _) => {
              Ok(Return(expr), parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_if(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, If) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(cond, parser3) => {
          match match_token(parser3, LBrace) {
            Ok(parser4, _) => {
              match parse_block(parser4, []) {
                Ok(then_branch, parser5) => {
                  match match_token(parser5, RBrace) {
                    Ok(parser6, _) => {
                      // check for else
                      let (else_branch, parser7) = if token_equals(peek(parser6), Else) {
                        let p2 = advance(parser6);
                        match match_token(p2, LBrace) {
                          Ok(p3, _) => {
                            match parse_block(p3, []) {
                              Ok(else_b, p4) => {
                                match match_token(p4, RBrace) {
                                  Ok(p5, _) => (Some(else_b), p5),
                                  Err(_) => (None, p4),
                                }
                              }
                              Err(_) => (None, p3),
                            }
                          }
                          Err(_) => (None, p2),
                        }
                      } else {
                        (None, parser6)
                      };

                      let stmt = If {
                        condition: cond,
                        then_branch: then_branch,
                        else_branch: else_branch,
                      };
                      Ok(stmt, parser7)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_match(parser: Parser) -> ParseResult(Statement) {
  // TODO: Match 문 파싱
  Err("Match not implemented yet")
}

fn parse_expression_statement(parser: Parser) -> ParseResult(Statement) {
  match parse_expression(parser) {
    Ok(expr, parser2) => {
      // optional semicolon
      let parser3 = if token_equals(peek(parser2), Semicolon) {
        advance(parser2)
      } else {
        parser2
      };
      Ok(Expression(expr), parser3)
    }
    Err(e) => Err(e)
  }
}

// ============================================================================
// Expression Parsing
// ============================================================================

fn parse_expression(parser: Parser) -> ParseResult(Expression) {
  parse_equality(parser)
}

fn parse_equality(parser: Parser) -> ParseResult(Expression) {
  match parse_comparison(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Eq | Ne => {
          let op = match peek(parser2) {
            Eq => "==",
            Ne => "!=",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_comparison(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_equality(parser4)  // left-associative
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_comparison(parser: Parser) -> ParseResult(Expression) {
  match parse_addition(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Lt | Le | Gt | Ge => {
          let op = match peek(parser2) {
            Lt => "<",
            Le => "<=",
            Gt => ">",
            Ge => ">=",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_addition(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_comparison(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_addition(parser: Parser) -> ParseResult(Expression) {
  match parse_multiplication(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Plus | Minus => {
          let op = match peek(parser2) {
            Plus => "+",
            Minus => "-",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_multiplication(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_addition(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_multiplication(parser: Parser) -> ParseResult(Expression) {
  match parse_unary(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Star | Slash | Percent => {
          let op = match peek(parser2) {
            Star => "*",
            Slash => "/",
            Percent => "%",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_unary(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_multiplication(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_unary(parser: Parser) -> ParseResult(Expression) {
  match peek(parser) {
    Not => {
      let parser2 = advance(parser);
      match parse_unary(parser2) {
        Ok(expr, parser3) => {
          let unary = UnaryOp {
            op: "!",
            operand: expr,
          };
          Ok(unary, parser3)
        }
        Err(e) => Err(e)
      }
    }
    Minus => {
      let parser2 = advance(parser);
      match parse_unary(parser2) {
        Ok(expr, parser3) => {
          let unary = UnaryOp {
            op: "-",
            operand: expr,
          };
          Ok(unary, parser3)
        }
        Err(e) => Err(e)
      }
    }
    _ => parse_call(parser)
  }
}

fn parse_call(parser: Parser) -> ParseResult(Expression) {
  match parse_primary(parser) {
    Ok(expr, parser2) => {
      match peek(parser2) {
        LParen => {
          // Function call
          match expr {
            Variable(name) => {
              let parser3 = advance(parser2);
              match parse_arguments(parser3, []) {
                Ok(args, parser4) => {
                  match match_token(parser4, RParen) {
                    Ok(parser5, _) => {
                      let call = FunctionCall {
                        name: name,
                        args: args,
                      };
                      parse_call(parser5)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            _ => Ok(expr, parser2)
          }
        }
        LBracket => {
          // Array indexing
          let parser3 = advance(parser2);
          match parse_expression(parser3) {
            Ok(index, parser4) => {
              match match_token(parser4, RBracket) {
                Ok(parser5, _) => {
                  let indexed = Index {
                    expr: expr,
                    index: index,
                  };
                  parse_call(parser5)
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(expr, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_primary(parser: Parser) -> ParseResult(Expression) {
  match peek(parser) {
    Integer(n) => {
      let parser2 = advance(parser);
      Ok(Literal(Integer(n)), parser2)
    }
    Float(f) => {
      let parser2 = advance(parser);
      Ok(Literal(Float(f)), parser2)
    }
    String(s) => {
      let parser2 = advance(parser);
      Ok(Literal(String(s)), parser2)
    }
    True => {
      let parser2 = advance(parser);
      Ok(Literal(Boolean(true)), parser2)
    }
    False => {
      let parser2 = advance(parser);
      Ok(Literal(Boolean(false)), parser2)
    }
    Identifier(name) => {
      let parser2 = advance(parser);
      Ok(Variable(name), parser2)
    }
    LParen => {
      let parser2 = advance(parser);
      match parse_expression(parser2) {
        Ok(expr, parser3) => {
          match match_token(parser3, RParen) {
            Ok(parser4, _) => {
              Ok(expr, parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    LBracket => {
      let parser2 = advance(parser);
      match parse_array_elements(parser2, []) {
        Ok(elements, parser3) => {
          match match_token(parser3, RBracket) {
            Ok(parser4, _) => {
              Ok(Array { elements: elements }, parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    If => parse_if_expr(parser),
    _ => Err("Unexpected token in expression")
  }
}

fn parse_arguments(parser: Parser, args: Vec(Expression)) -> ParseResult(Vec(Expression)) {
  if token_equals(peek(parser), RParen) {
    Ok(args, parser)
  } else {
    match parse_expression(parser) {
      Ok(expr, parser2) => {
        let new_args = vec_append(args, expr);
        if token_equals(peek(parser2), Comma) {
          parse_arguments(advance(parser2), new_args)
        } else {
          Ok(new_args, parser2)
        }
      }
      Err(e) => Err(e)
    }
  }
}

fn parse_array_elements(parser: Parser, elements: Vec(Expression)) -> ParseResult(Vec(Expression)) {
  if token_equals(peek(parser), RBracket) {
    Ok(elements, parser)
  } else {
    match parse_expression(parser) {
      Ok(expr, parser2) => {
        let new_elements = vec_append(elements, expr);
        if token_equals(peek(parser2), Comma) {
          parse_array_elements(advance(parser2), new_elements)
        } else {
          Ok(new_elements, parser2)
        }
      }
      Err(e) => Err(e)
    }
  }
}

fn parse_if_expr(parser: Parser) -> ParseResult(Expression) {
  match match_token(parser, If) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(cond, parser3) => {
          match match_token(parser3, LBrace) {
            Ok(parser4, _) => {
              match parse_expression(parser4) {
                Ok(then_e, parser5) => {
                  match match_token(parser5, RBrace) {
                    Ok(parser6, _) => {
                      let (else_e, parser7) = if token_equals(peek(parser6), Else) {
                        let p2 = advance(parser6);
                        match match_token(p2, LBrace) {
                          Ok(p3, _) => {
                            match parse_expression(p3) {
                              Ok(e, p4) => {
                                match match_token(p4, RBrace) {
                                  Ok(p5, _) => (Some(e), p5),
                                  Err(_) => (None, p4),
                                }
                              }
                              Err(_) => (None, p3),
                            }
                          }
                          Err(_) => (None, p2),
                        }
                      } else {
                        (None, parser6)
                      };

                      let expr = IfExpr {
                        condition: cond,
                        then_expr: then_e,
                        else_expr: else_e,
                      };
                      Ok(expr, parser7)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    Err(e) => Err(e)
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

// 타입 스킵 (현재는 간단히 구현)
fn skip_type(parser: Parser) -> Parser {
  match peek(parser) {
    Identifier(_) => {
      let parser2 = advance(parser);
      // check for array suffix [...]
      if token_equals(peek(parser2), LBracket) {
        skip_type(advance(parser2))
      } else {
        parser2
      }
    }
    _ => parser
  }
}

// ============================================================================
// Vector Utilities (필요한 stdlib 함수들)
// ============================================================================

// NOTE: 다음은 FV 표준 라이브러리에서 제공되어야 함
// - vec_length(v: Vec(T)) -> i64
// - vec_get(v: Vec(T), i: i64) -> T
// - vec_append(v: Vec(T), e: T) -> Vec(T)

toolUseResult.content:
// Parser: Tokens → Abstract Syntax Tree
// 토큰 스트림을 AST로 변환
// 재귀 하강 파싱 (Recursive Descent Parser)

// 파서 상태
type Parser = {
  tokens: Vec(Token),
  pos: i64,
}

// 파싱 결과
type ParseResult(T) =
  | Ok(T, Parser)
  | Err(String)

// 상수
fn MAX_PARSE_DEPTH() -> i64 {
  1000
}

fn MAX_TOKENS() -> i64 {
  100_000
}

// ============================================================================
// Parser Creation
// ============================================================================

fn create_parser(tokens: Vec(Token)) -> ParseResult(Parser) {
  if vec_length(tokens) > MAX_TOKENS() {
    Err("Too many tokens")
  } else {
    Ok(
      Parser {
        tokens: tokens,
        pos: 0,
      },
      Parser { tokens: tokens, pos: 0 }
    )
  }
}

// ============================================================================
// Low-level Parser Functions
// ============================================================================

// 현재 토큰 반환
fn peek(parser: Parser) -> Token {
  let tokens = parser.tokens;
  let pos = parser.pos;
  if pos >= vec_length(tokens) {
    Eof
  } else {
    vec_get(tokens, pos)
  }
}

// 다음 토큰으로 진행
fn advance(parser: Parser) -> Parser {
  Parser {
    tokens: parser.tokens,
    pos: parser.pos + 1,
  }
}

// 현재 위치 끝났나?
fn is_at_end(parser: Parser) -> bool {
  parser.pos >= vec_length(parser.tokens)
}

// 토큰 매칭
fn match_token(parser: Parser, expected: Token) -> ParseResult(Parser) {
  if token_equals(peek(parser), expected) {
    Ok(advance(parser), parser)
  } else {
    Err("Token mismatch")
  }
}

// 토큰이 특정 타입인지 확인
fn token_equals(t1: Token, t2: Token) -> bool {
  match (t1, t2) {
    (Fn, Fn) => true,
    (Let, Let) => true,
    (If, If) => true,
    (Else, Else) => true,
    (Match, Match) => true,
    (Return, Return) => true,
    (Type, Type) => true,
    (Identifier(_), Identifier(_)) => true,
    (Integer(_), Integer(_)) => true,
    (Float(_), Float(_)) => true,
    (String(_), String(_)) => true,
    (True, True) => true,
    (False, False) => true,
    (Plus, Plus) => true,
    (Minus, Minus) => true,
    (Star, Star) => true,
    (Slash, Slash) => true,
    (Eq, Eq) => true,
    (Lt, Lt) => true,
    (Gt, Gt) => true,
    (LParen, LParen) => true,
    (RParen, RParen) => true,
    (LBrace, LBrace) => true,
    (RBrace, RBrace) => true,
    (LBracket, LBracket) => true,
    (RBracket, RBracket) => true,
    (Comma, Comma) => true,
    (Dot, Dot) => true,
    (Colon, Colon) => true,
    (Semicolon, Semicolon) => true,
    (Arrow, Arrow) => true,
    (FatArrow, FatArrow) => true,
    (Eof, Eof) => true,
    _ => false,
  }
}

// ============================================================================
// Main Parser
// ============================================================================

fn parse(parser: Parser) -> ParseResult(Program) {
  parse_definitions(parser, [], [])
}

fn parse_definitions(
  parser: Parser,
  defs: Vec(Definition),
  stmts: Vec(Statement)
) -> ParseResult(Program) {
  if is_at_end(parser) {
    Ok(
      Program {
        definitions: defs,
        statements: stmts,
      },
      parser
    )
  } else {
    match peek(parser) {
      Fn => {
        match parse_function(parser) {
          Ok(def, parser2) => {
            let new_defs = vec_append(defs, def);
            parse_definitions(parser2, new_defs, stmts)
          }
          Err(e) => Err(e)
        }
      }
      Type => {
        match parse_type_def(parser) {
          Ok(def, parser2) => {
            let new_defs = vec_append(defs, def);
            parse_definitions(parser2, new_defs, stmts)
          }
          Err(e) => Err(e)
        }
      }
      Eof => {
        Ok(
          Program {
            definitions: defs,
            statements: stmts,
          },
          parser
        )
      }
      _ => {
        match parse_statement(parser) {
          Ok(stmt, parser2) => {
            let new_stmts = vec_append(stmts, stmt);
            parse_definitions(parser2, defs, new_stmts)
          }
          Err(e) => Err(e)
        }
      }
    }
  }
}

// ============================================================================
// Function Definition
// ============================================================================

fn parse_function(parser: Parser) -> ParseResult(Definition) {
  // expect Fn
  match match_token(parser, Fn) {
    Ok(parser2, _) => {
      // read function name
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          // expect (
          match match_token(parser3, LParen) {
            Ok(parser4, _) => {
              // parse parameters
              match parse_parameters(parser4, []) {
                Ok(params, parser5) => {
                  // expect )
                  match match_token(parser5, RParen) {
                    Ok(parser6, _) => {
                      // expect ->
                      match match_token(parser6, Arrow) {
                        Ok(parser7, _) => {
                          // parse return type (skip for now)
                          let parser8 = skip_type(parser7);
                          // expect {
                          match match_token(parser8, LBrace) {
                            Ok(parser9, _) => {
                              // parse body
                              match parse_block(parser9, []) {
                                Ok(body, parser10) => {
                                  // expect }
                                  match match_token(parser10, RBrace) {
                                    Ok(parser11, _) => {
                                      let def = Function {
                                        name: name,
                                        params: params,
                                        body: body,
                                      };
                                      Ok(def, parser11)
                                    }
                                    Err(e) => Err(e)
                                  }
                                }
                                Err(e) => Err(e)
                              }
                            }
                            Err(e) => Err(e)
                          }
                        }
                        Err(e) => Err(e)
                      }
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected function name")
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_parameters(parser: Parser, params: Vec(String)) -> ParseResult(Vec(String)) {
  if token_equals(peek(parser), RParen) {
    Ok(params, parser)
  } else {
    match peek(parser) {
      Identifier(name) => {
        let parser2 = advance(parser);
        // skip optional type annotation
        let parser3 = if token_equals(peek(parser2), Colon) {
          let p = advance(parser2);
          skip_type(p)
        } else {
          parser2
        };
        let new_params = vec_append(params, name);
        if token_equals(peek(parser3), Comma) {
          parse_parameters(advance(parser3), new_params)
        } else {
          Ok(new_params, parser3)
        }
      }
      _ => Err("Expected parameter name")
    }
  }
}

// ============================================================================
// Type Definition
// ============================================================================

fn parse_type_def(parser: Parser) -> ParseResult(Definition) {
  match match_token(parser, Type) {
    Ok(parser2, _) => {
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          match match_token(parser3, Assign) {
            Ok(parser4, _) => {
              let parser5 = skip_type(parser4);
              match match_token(parser5, Semicolon) {
                Ok(parser6, _) => {
                  let def = TypeDef { name: name };
                  Ok(def, parser6)
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected type name")
      }
    }
    Err(e) => Err(e)
  }
}

// ============================================================================
// Block Parsing
// ============================================================================

fn parse_block(parser: Parser, stmts: Vec(Statement)) -> ParseResult(Vec(Statement)) {
  if token_equals(peek(parser), RBrace) || is_at_end(parser) {
    Ok(stmts, parser)
  } else {
    match parse_statement(parser) {
      Ok(stmt, parser2) => {
        let new_stmts = vec_append(stmts, stmt);
        parse_block(parser2, new_stmts)
      }
      Err(e) => Err(e)
    }
  }
}

// ============================================================================
// Statement Parsing
// ============================================================================

fn parse_statement(parser: Parser) -> ParseResult(Statement) {
  match peek(parser) {
    Let => parse_let_binding(parser),
    Return => parse_return(parser),
    If => parse_if(parser),
    Match => parse_match(parser),
    _ => parse_expression_statement(parser),
  }
}

fn parse_let_binding(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, Let) {
    Ok(parser2, _) => {
      match peek(parser2) {
        Identifier(name) => {
          let parser3 = advance(parser2);
          match match_token(parser3, Assign) {
            Ok(parser4, _) => {
              match parse_expression(parser4) {
                Ok(expr, parser5) => {
                  match match_token(parser5, Semicolon) {
                    Ok(parser6, _) => {
                      let stmt = LetBinding {
                        name: name,
                        value: expr,
                      };
                      Ok(stmt, parser6)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Err("Expected variable name")
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_return(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, Return) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(expr, parser3) => {
          match match_token(parser3, Semicolon) {
            Ok(parser4, _) => {
              Ok(Return(expr), parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_if(parser: Parser) -> ParseResult(Statement) {
  match match_token(parser, If) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(cond, parser3) => {
          match match_token(parser3, LBrace) {
            Ok(parser4, _) => {
              match parse_block(parser4, []) {
                Ok(then_branch, parser5) => {
                  match match_token(parser5, RBrace) {
                    Ok(parser6, _) => {
                      // check for else
                      let (else_branch, parser7) = if token_equals(peek(parser6), Else) {
                        let p2 = advance(parser6);
                        match match_token(p2, LBrace) {
                          Ok(p3, _) => {
                            match parse_block(p3, []) {
                              Ok(else_b, p4) => {
                                match match_token(p4, RBrace) {
                                  Ok(p5, _) => (Some(else_b), p5),
                                  Err(_) => (None, p4),
                                }
                              }
                              Err(_) => (None, p3),
                            }
                          }
                          Err(_) => (None, p2),
                        }
                      } else {
                        (None, parser6)
                      };

                      let stmt = If {
                        condition: cond,
                        then_branch: then_branch,
                        else_branch: else_branch,
                      };
                      Ok(stmt, parser7)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_match(parser: Parser) -> ParseResult(Statement) {
  // TODO: Match 문 파싱
  Err("Match not implemented yet")
}

fn parse_expression_statement(parser: Parser) -> ParseResult(Statement) {
  match parse_expression(parser) {
    Ok(expr, parser2) => {
      // optional semicolon
      let parser3 = if token_equals(peek(parser2), Semicolon) {
        advance(parser2)
      } else {
        parser2
      };
      Ok(Expression(expr), parser3)
    }
    Err(e) => Err(e)
  }
}

// ============================================================================
// Expression Parsing
// ============================================================================

fn parse_expression(parser: Parser) -> ParseResult(Expression) {
  parse_equality(parser)
}

fn parse_equality(parser: Parser) -> ParseResult(Expression) {
  match parse_comparison(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Eq | Ne => {
          let op = match peek(parser2) {
            Eq => "==",
            Ne => "!=",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_comparison(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_equality(parser4)  // left-associative
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_comparison(parser: Parser) -> ParseResult(Expression) {
  match parse_addition(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Lt | Le | Gt | Ge => {
          let op = match peek(parser2) {
            Lt => "<",
            Le => "<=",
            Gt => ">",
            Ge => ">=",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_addition(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_comparison(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_addition(parser: Parser) -> ParseResult(Expression) {
  match parse_multiplication(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Plus | Minus => {
          let op = match peek(parser2) {
            Plus => "+",
            Minus => "-",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_multiplication(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_addition(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_multiplication(parser: Parser) -> ParseResult(Expression) {
  match parse_unary(parser) {
    Ok(left, parser2) => {
      match peek(parser2) {
        Star | Slash | Percent => {
          let op = match peek(parser2) {
            Star => "*",
            Slash => "/",
            Percent => "%",
            _ => "?",
          };
          let parser3 = advance(parser2);
          match parse_unary(parser3) {
            Ok(right, parser4) => {
              let expr = BinaryOp {
                op: op,
                left: left,
                right: right,
              };
              parse_multiplication(parser4)
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(left, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_unary(parser: Parser) -> ParseResult(Expression) {
  match peek(parser) {
    Not => {
      let parser2 = advance(parser);
      match parse_unary(parser2) {
        Ok(expr, parser3) => {
          let unary = UnaryOp {
            op: "!",
            operand: expr,
          };
          Ok(unary, parser3)
        }
        Err(e) => Err(e)
      }
    }
    Minus => {
      let parser2 = advance(parser);
      match parse_unary(parser2) {
        Ok(expr, parser3) => {
          let unary = UnaryOp {
            op: "-",
            operand: expr,
          };
          Ok(unary, parser3)
        }
        Err(e) => Err(e)
      }
    }
    _ => parse_call(parser)
  }
}

fn parse_call(parser: Parser) -> ParseResult(Expression) {
  match parse_primary(parser) {
    Ok(expr, parser2) => {
      match peek(parser2) {
        LParen => {
          // Function call
          match expr {
            Variable(name) => {
              let parser3 = advance(parser2);
              match parse_arguments(parser3, []) {
                Ok(args, parser4) => {
                  match match_token(parser4, RParen) {
                    Ok(parser5, _) => {
                      let call = FunctionCall {
                        name: name,
                        args: args,
                      };
                      parse_call(parser5)
                    }
                    Err(e) => Err(e)
                  }
                }
                Err(e) => Err(e)
              }
            }
            _ => Ok(expr, parser2)
          }
        }
        LBracket => {
          // Array indexing
          let parser3 = advance(parser2);
          match parse_expression(parser3) {
            Ok(index, parser4) => {
              match match_token(parser4, RBracket) {
                Ok(parser5, _) => {
                  let indexed = Index {
                    expr: expr,
                    index: index,
                  };
                  parse_call(parser5)
                }
                Err(e) => Err(e)
              }
            }
            Err(e) => Err(e)
          }
        }
        _ => Ok(expr, parser2)
      }
    }
    Err(e) => Err(e)
  }
}

fn parse_primary(parser: Parser) -> ParseResult(Expression) {
  match peek(parser) {
    Integer(n) => {
      let parser2 = advance(parser);
      Ok(Literal(Integer(n)), parser2)
    }
    Float(f) => {
      let parser2 = advance(parser);
      Ok(Literal(Float(f)), parser2)
    }
    String(s) => {
      let parser2 = advance(parser);
      Ok(Literal(String(s)), parser2)
    }
    True => {
      let parser2 = advance(parser);
      Ok(Literal(Boolean(true)), parser2)
    }
    False => {
      let parser2 = advance(parser);
      Ok(Literal(Boolean(false)), parser2)
    }
    Identifier(name) => {
      let parser2 = advance(parser);
      Ok(Variable(name), parser2)
    }
    LParen => {
      let parser2 = advance(parser);
      match parse_expression(parser2) {
        Ok(expr, parser3) => {
          match match_token(parser3, RParen) {
            Ok(parser4, _) => {
              Ok(expr, parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    LBracket => {
      let parser2 = advance(parser);
      match parse_array_elements(parser2, []) {
        Ok(elements, parser3) => {
          match match_token(parser3, RBracket) {
            Ok(parser4, _) => {
              Ok(Array { elements: elements }, parser4)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
