fn parse_arguments(parser: Parser, args: Vec(Expression)) -> ParseResult(Vec(Expression)) {
  if token_equals(peek(parser), RParen) {
    Ok(args, parser)
  } else {
    match parse_expression(parser) {
      Ok(expr, parser2) => {
        let new_args = vec_append(args, expr);
        if token_equals(peek(parser2), Comma) {
          parse_arguments(advance(parser2), new_args)
        } else {
          Ok(new_args, parser2)
        }
      }
      Err(e) => Err(e)
    }
  }
}

fn parse_array_elements(parser: Parser, elements: Vec(Expression)) -> ParseResult(Vec(Expression)) {
  if token_equals(peek(parser), RBracket) {
    Ok(elements, parser)
  } else {
    match parse_expression(parser) {
      Ok(expr, parser2) => {
        let new_elements = vec_append(elements, expr);
        if token_equals(peek(parser2), Comma) {
