fn parse_if_expr(parser: Parser) -> ParseResult(Expression) {
  match match_token(parser, If) {
    Ok(parser2, _) => {
      match parse_expression(parser2) {
        Ok(cond, parser3) => {
          match match_token(parser3, LBrace) {
            Ok(parser4, _) => {
