    }
    Variable(name) => {
      Ok(name, ctx)
    }
    BinaryOp { op: o, left: l, right: r } => {
      match generate_expression(l, ctx) {
        Ok(left_code, ctx2) => {
          match generate_expression(r, ctx2) {
            Ok(right_code, ctx3) => {
