                "-" => "-",
                "*" => "*",
                "/" => "/",
                "%" => "%",
                "==" => "==",
                "!=" => "!=",
                "<" => "<",
                "<=" => "<=",
                ">" => ">",
                ">=" => ">=",
                "&&" => "&&",
                "||" => "||",
                _ => "?",
              };
