            string_concat(opnd_code, ")")
          );
          Ok(unary, ctx2)
        }
        Err(e) => Err(e)
      }
    }
    FunctionCall { name: fn_name, args: a } => {
      match generate_expression_list(a, ctx, "") {
        Ok(args_code, ctx2) => {
          let call = string_concat(
            string_concat(fn_name, "("),
            string_concat(args_code, ")")
          );
          Ok(call, ctx2)
        }
        Err(e) => Err(e)
      }
    }
    Array { elements: _ } => {
      // Array literals need special handling
      Err("Array literals not yet supported")
    }
    Index { expr: e, index: idx } => {
      match generate_expression(e, ctx) {
        Ok(e_code, ctx2) => {
          match generate_expression(idx, ctx2) {
            Ok(idx_code, ctx3) => {
