                string_concat(e_code, "["),
                string_concat(idx_code, "]")
              );
              Ok(indexed, ctx3)
            }
            Err(e) => Err(e)
          }
        }
        Err(e) => Err(e)
      }
    }
    _ => Err("Expression type not yet supported")
  }
