          };
          collect_function_signatures(rest, new_ctx)
        }
        _ => {
          collect_function_signatures(rest, ctx)
        }
      }
    }
  }
}

fn increment_indent(ctx: CodeGenContext) -> CodeGenContext {
  CodeGenContext {
    functions: ctx.functions,
    variables: ctx.variables,
    indent_level: ctx.indent_level + 1,
  }
}

fn get_indent(level: i64) -> String {
  if level <= 0 {
    ""
  } else {
    string_concat("  ", get_indent(level - 1))
  }
}

